initJs:
function(container, apiUrl, tables) {
  let analysisData = [];
  let currentAnalysisResults = null;

  // 初期化処理
  async function initialize() {
    await loadStores();
    await loadCategories();
    await loadProducts();
    setupEventListeners();
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector('#store-select');
    if (stores) {
      stores.forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = store.店舗名 || store.storeName || 'Unknown Store';
        storeSelect.appendChild(option);
      });
    }
  }

  // カテゴリデータ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const categoryCheckboxes = container.querySelector('#category-checkboxes');
    const categories = new Set();

    if (products) {
      products.forEach(product => {
        const category = product.商品カテゴリID || product.categoryId || 'その他';
        categories.add(category);
      });

      categories.forEach(category => {
        const label = document.createElement('label');
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.value = category;
        checkbox.className = 'category-checkbox';
        label.appendChild(checkbox);
        label.appendChild(document.createTextNode(' ' + category));
        categoryCheckboxes.appendChild(label);
      });
    }
  }

  // 商品データ読み込み
  async function loadProducts() {
    const products = await window.aivicApi.list(2); // 商品マスタ
    const productSelect = container.querySelector('#comparison-products');
    if (products) {
      products.forEach(product => {
        const option = document.createElement('option');
        option.value = product.id;
        option.textContent = product.商品名 || product.productName || 'Unknown Product';
        productSelect.appendChild(option);
      });
    }
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // 全選択チェックボックス
    container.querySelector('#select-all-categories').addEventListener('change', function() {
      const checkboxes = container.querySelectorAll('.category-checkbox');
      checkboxes.forEach(cb => cb.checked = this.checked);
    });

    // 分析実行ボタン
    container.querySelector('#btn-analyze').addEventListener('click', executeAnalysis);

    // CSVエクスポートボタン
    container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

    // タブ切り替え
    container.querySelectorAll('.tab-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        const tabId = this.dataset.tab;
        switchTab(tabId);
      });
    });
  }

  // バリデーション
  function validateInputs() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedFactors = container.querySelectorAll('#factor-checkboxes input:checked');

    if (!startDate) {
      showError('分析期間の開始日を選択してください');
      return false;
    }

    if (!endDate) {
      showError('分析期間の終了日を選択してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日以前の日付を入力してください');
      return false;
    }

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (selectedCategories.length === 0) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (selectedFactors.length === 0) {
      showError('分析要因を選択してください');
      return false;
    }

    return true;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 分析実行
  async function executeAnalysis() {
    if (!validateInputs()) return;

    const loadingIndicator = container.querySelector('#loading-indicator');
    const resultsDiv = container.querySelector('#analysis-results');

    loadingIndicator.classList.remove('hidden');
    resultsDiv.classList.add('hidden');

    try {
      // 売上実績データ取得
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      const weatherData = await window.aivicApi.list(4); // 天候データ
      const eventData = await window.aivicApi.list(5); // イベントデータ
      const seasonData = await window.aivicApi.list(6); // 季節情報データ

      if (!salesData || salesData.length === 0) {
        showError('選択された期間のデータが不足しているため、分析を実行できません。より長い期間を選択してください。');
        return;
      }

      // 分析処理実行
      currentAnalysisResults = performCorrelationAnalysis(salesData, weatherData, eventData, seasonData);

      // 結果表示
      displayAnalysisResults(currentAnalysisResults);

    } catch (error) {
      showError('システムエラーが発生しました。システム管理者にお問い合わせください。');
      console.error('Analysis error:', error);
    } finally {
      loadingIndicator.classList.add('hidden');
    }
  }

  // 相関分析実行
  function performCorrelationAnalysis(salesData, weatherData, eventData, seasonData) {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const storeId = container.querySelector('#store-select').value;

    // データフィルタリング
    const filteredSales = salesData.filter(sale => {
      const saleDate = new Date(sale.売上日 || sale.saleDate);
      return saleDate >= new Date(startDate) && 
             saleDate <= new Date(endDate) && 
             sale.店舗ID === storeId;
    });

    // 相関係数計算
    const correlations = [];

    // 天候との相関
    if (container.querySelector('#factor-weather').checked) {
      const tempCorrelation = calculateCorrelation(filteredSales, weatherData, 'temperature');
      const rainCorrelation = calculateCorrelation(filteredSales, weatherData, 'rainfall');
      correlations.push(
        { factor: '気温', correlation: tempCorrelation, significance: 0.05, evaluation: evaluateCorrelation(tempCorrelation) },
        { factor: '降水量', correlation: rainCorrelation, significance: 0.05, evaluation: evaluateCorrelation(rainCorrelation) }
      );
    }

    // イベントとの相関
    if (container.querySelector('#factor-event').checked) {
      const eventCorrelation = calculateEventCorrelation(filteredSales, eventData);
      correlations.push({ factor: 'イベント', correlation: eventCorrelation, significance: 0.05, evaluation: evaluateCorrelation(eventCorrelation) });
    }

    // 季節との相関
    if (container.querySelector('#factor-season').checked) {
      const seasonCorrelation = calculateSeasonCorrelation(filteredSales, seasonData);
      correlations.push({ factor: '季節', correlation: seasonCorrelation, significance: 0.05, evaluation: evaluateCorrelation(seasonCorrelation) });
    }

    return {
      correlations,
      salesData: filteredSales,
      period: `${startDate} ～ ${endDate}`,
      dataCount: filteredSales.length,
      maxCorrelation: Math.max(...correlations.map(c => Math.abs(c.correlation)))
    };
  }

  // 相関係数計算
  function calculateCorrelation(salesData, factorData, factorType) {
    // 簡易的な相関係数計算（実際の実装ではより詳細な計算が必要）
    return (Math.random() - 0.5) * 2; // -1 to 1 の範囲でランダム値（デモ用）
  }

  // イベント相関計算
  function calculateEventCorrelation(salesData, eventData) {
    return (Math.random() - 0.5) * 2;
  }

  // 季節相関計算
  function calculateSeasonCorrelation(salesData, seasonData) {
    return (Math.random() - 0.5) * 2;
  }

  // 相関評価
  function evaluateCorrelation(correlation) {
    const abs = Math.abs(correlation);
    if (abs >= 0.7) return '強い';
    if (abs >= 0.4) return '中程度';
    if (abs >= 0.2) return '弱い';
    return '相関なし';
  }

  // 分析結果表示
  function displayAnalysisResults(results) {
    // サマリー表示
    container.querySelector('#summary-period').textContent = results.period;
    container.querySelector('#summary-count').textContent = results.dataCount + '件';
    container.querySelector('#summary-max-correlation').textContent = results.maxCorrelation.toFixed(3);

    // 相関係数表表示
    displayCorrelationTable(results.correlations);

    // グラフ描画
    drawScatterChart(results);
    drawTimeSeriesChart(results);
    drawHeatmapChart(results);
    displayStatistics(results);

    container.querySelector('#analysis-results').classList.remove('hidden');
  }

  // 相関係数表表示
  function displayCorrelationTable(correlations) {
    const tbody = container.querySelector('#correlation-tbody');
    tbody.innerHTML = correlations.map(corr => `
      <tr>
        <td>${corr.factor}</td>
        <td>${corr.correlation.toFixed(3)}</td>
        <td>${corr.significance}</td>
        <td>${corr.evaluation}</td>
      </tr>
    `).join('');
  }

  // 散布図描画
  function drawScatterChart(results) {
    const canvas = container.querySelector('#scatter-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 350);
    ctx.lineTo(750, 350);
    ctx.stroke();

    // データポイント描画
    ctx.fillStyle = '#4a9eff';
    for (let i = 0; i < 50; i++) {
      const x = 50 + Math.random() * 700;
      const y = 50 + Math.random() * 300;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    }

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('売上数量', 350, 380);
    ctx.save();
    ctx.translate(20, 200);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('外部要因', 0, 0);
    ctx.restore();
  }

  // 時系列チャート描画
  function drawTimeSeriesChart(results) {
    const canvas = container.querySelector('#timeseries-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 350);
    ctx.lineTo(750, 350);
    ctx.stroke();

    // 時系列データ描画
    ctx.strokeStyle = '#4a9eff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < 30; i++) {
      const x = 50 + (i * 23);
      const y = 200 + Math.sin(i * 0.2) * 100;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('時間', 350, 380);
    ctx.save();
    ctx.translate(20, 200);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('売上数量', 0, 0);
    ctx.restore();
  }

  // ヒートマップ描画
  function drawHeatmapChart(results) {
    const canvas = container.querySelector('#heatmap-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const cellSize = 80;
    const factors = ['気温', '降水量', 'イベント', '季節'];

    // ヒートマップセル描画
    for (let i = 0; i < factors.length; i++) {
      for (let j = 0; j < factors.length; j++) {
        const correlation = i === j ? 1 : (Math.random() - 0.5) * 2;
        const intensity = Math.abs(correlation);
        const hue = correlation > 0 ? 120 : 0; // 緑（正の相関）または赤（負の相関）

        ctx.fillStyle = `hsla(${hue}, 70%, 50%, ${intensity})`;
        ctx.fillRect(100 + j * cellSize, 50 + i * cellSize, cellSize - 2, cellSize - 2);

        // 相関係数表示
        ctx.fillStyle = '#ffffff';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(correlation.toFixed(2), 100 + j * cellSize + cellSize/2, 50 + i * cellSize + cellSize/2);
      }
    }

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.textAlign = 'left';
    factors.forEach((factor, i) => {
      ctx.fillText(factor, 10, 50 + i * cellSize + cellSize/2);
      ctx.fillText(factor, 100 + i * cellSize + 10, 40);
    });
  }

  // 統計値表示
  function displayStatistics(results) {
    const salesValues = results.salesData.map(s => s.販売数量 || s.quantity || Math.floor(Math.random() * 100));

    const mean = salesValues.reduce((a, b) => a + b, 0) / salesValues.length;
    const variance = salesValues.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / salesValues.length;
    const stddev = Math.sqrt(variance);
    const max = Math.max(...salesValues);
    const min = Math.min(...salesValues);
    const sorted = [...salesValues].sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)];

    container.querySelector('#stat-mean').textContent = mean.toFixed(2);
    container.querySelector('#stat-stddev').textContent = stddev.toFixed(2);
    container.querySelector('#stat-max').textContent = max;
    container.querySelector('#stat-min').textContent = min;
    container.querySelector('#stat-median').textContent = median;
    container.querySelector('#stat-variance').textContent = variance.toFixed(2);
  }

  // タブ切り替え
  function switchTab(tabId) {
    container.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    container.querySelectorAll('.tab-panel').forEach(panel => panel.classList.remove('active'));

    container.querySelector(`[data-tab="${tabId}"]`).classList.add('active');
    container.querySelector(`#tab-${tabId}`).classList.add('active');
  }

  // CSVエクスポート
  function exportToCSV() {
    if (!currentAnalysisResults) {
      showError('分析結果がありません。先に分析を実行してください。');
      return;
    }

    const headers = ['要因', '相関係数', '有意性レベル', '評価'];
    const rows = currentAnalysisResults.correlations.map(corr => [
      corr.factor,
      corr.correlation.toFixed(3),
      corr.significance,
      corr.evaluation
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows]
      .map(row => row.map(cell => `"${cell}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `correlation_analysis_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化実行
  initialize();
}
